        vscode.postMessage({ type: 'debugLog', message: '[WV-FOLDSTICKY] ensureTurnFoldStructure KEEPING OPEN (sticky): body._userExpanded=' + body._userExpanded + ' turnKey=' + _turnKey + ' durable=' + _durableExpanded });
